  class ContextRanker { public function rankFiles(array $files, string $query): array { $keywords = array_filter(explode(' ', strtolower(preg_replace('/[^a-zA-Z0-9_\s]/', '', $query)))); $scoredFiles = []; foreach ($files as $relativePath => $info) { $score = $this->calculateScore($relativePath, $info, $keywords); $info['score'] = $score; $scoredFiles[$relativePath] = $info; } uasort($scoredFiles, function ($a, $b) { return $b['score'] <=> $a['score']; }); return $scoredFiles; } private function calculateScore(string $path, array $info, array $keywords): int { $score = 0; $lowerPath = strtolower($path); if (in_array($path, ['composer.json', 'README.md', 'FEATURES.md', 'ARCHITECTURE.md', 'docs/CLI_COMMANDS_REFERENCE.md'])) { $score += 15; } if (str_contains($lowerPath, 'app/domain/')) $score += 10; if (str_contains($lowerPath, 'app/usecases/')) $score += 10; if (str_contains($lowerPath, 'app/adapters/')) $score += 8; foreach ($keywords as $kw) { if (empty($kw) || strlen($kw) < 2) continue; if (str_contains($lowerPath, $kw)) { $score += 25; } $singular = rtrim($kw, 's'); if (!empty($singular) && str_contains($lowerPath, $singular)) { $score += 15; } } return $score; } } 